ALTER TABLE "WorkoutExercise" ADD COLUMN "studentProgress" JSONB;
ALTER TABLE "WorkoutFeedback" ADD COLUMN "photo" TEXT NOT NULL DEFAULT '';
ALTER TABLE "WorkoutFeedback" ADD COLUMN "groupId" TEXT REFERENCES "FitnessGroup"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "FitnessGroup" ("id" TEXT NOT NULL PRIMARY KEY,"ownerId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"inviteCode" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "FitnessGroup_inviteCode_key" ON "FitnessGroup"("inviteCode");
CREATE TABLE "FitnessGroupMember" ("id" TEXT NOT NULL PRIMARY KEY,"groupId" TEXT NOT NULL,"accountId" TEXT NOT NULL,"joinedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("groupId") REFERENCES "FitnessGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY("accountId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "FitnessGroupMember_groupId_accountId_key" ON "FitnessGroupMember"("groupId","accountId");
CREATE TABLE "FitnessChallenge" ("id" TEXT NOT NULL PRIMARY KEY,"groupId" TEXT NOT NULL,"title" TEXT NOT NULL,"startsAt" TEXT NOT NULL,"endsAt" TEXT NOT NULL,"goal" INTEGER NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("groupId") REFERENCES "FitnessGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE);
